def create_gold_csv(path):
    """Write the hand-written gold set to CSV with ground-truth labels."""
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(path, "w", newline="", encoding="utf-8") as f:
        writer = csv.writer(f)
        writer.writerow(["id", "location", "platform", "rating", "text", "date",
                         "language", "sentiment", "aspects", "crisis_flag",
                         "crisis_category", "severity"])
        for i, (text, rating, location, lang, sentiment, aspects,
                crisis, cat, severity) in enumerate(GOLD_REVIEWS):
            aspect_str = "|".join(f"{a}:{s}" for a, s in aspects)
            writer.writerow([
                f"hw_{i+1:03d}", location, "Google Reviews", rating, text,
                "2026-10-23", lang, sentiment, aspect_str,
                str(crisis).lower(), cat, severity
            ])
    print(f"Manually-authored gold set saved: {len(GOLD_REVIEWS)} reviews -> {path}")


if __name__ == "__main__":
    create_gold_csv(Path(__file__).resolve().parent / "reviews_hand_written_gold.csv")

